def _make_lesson(
    lid: str,
    mod: int,
    lnum: int,
    tvi: str,
    ten: str,
    tzh: str,
    qvi: str,
    qen: str,
    svi: str,
    sen: str,
    evi: str,
    een: str,
    exzh: str,
    exvi: str,
    exen: str,
    vdiag_vi: str,
    vdiag_en: str,
    vn_vi: str,
    vn_en: str,
    terms: list[tuple[str, str, str, str, str]],
    next_vi: str,
    next_en: str,
    rlink_page: str,
    rlink_vi: str,
    rlink_en: str,
    cq_vi: str,
    cq_en: str,
    ans_vi: str,
    ans_en: str,
    img: str,
) -> dict[str, Any]:
    return {
        "id": lid,
        "moduleNum": mod,
        "lessonNum": lnum,
        "titleVi": tvi,
        "titleEn": ten,
        "titleZh": tzh,
        "coreQuestionVi": qvi,
        "coreQuestionEn": qen,
        "synthesisParagraphVi": svi,
        "synthesisParagraphEn": sen,
        "historicalEvidenceVi": evi,
        "historicalEvidenceEn": een,
        "primaryTextExcerptZh": exzh,
        "primaryTextExcerptVi": exvi,
        "primaryTextExcerptEn": exen,
        "visualDiagramSpecVi": vdiag_vi,
        "visualDiagramSpecEn": vdiag_en,
        "vietnamComparisonVi": vn_vi,
        "vietnamComparisonEn": vn_en,
        "keyTermsTrilingual": [
            {"zh": z, "pinyin": p, "hanViet": h, "vi": v, "en": e} for z, p, h, v, e in terms
        ],
        "logicalLinkToNextVi": next_vi,
        "logicalLinkToNextEn": next_en,
        "readingLink": {"page": rlink_page, "labelVi": rlink_vi, "labelEn": rlink_en},
        "checkpointQuiz": {"qVi": cq_vi, "qEn": cq_en, "ansVi": ans_vi, "ansEn": ans_en},
        "imagePath": ensure_verified_img(img),
    }


